return ['domain'=>'tranzly','plural-forms'=>'nplurals=3; plural=(((((((0 == 0)) && ((((n == 0)) == 0))) && (((n % 1000000) == 0))) && ((0 == 0))) || ((((0 >= 0 && 0 <= 5)) == 0))) ? 1 : ((n == 0) || (n == 1)) ? 0 : 2);','language'=>'fr_FR','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'WordPress multilingue, un article par langue : traductions liées d\'articles, de pages, de catégories, de texte média, de widgets et du titre du site, avec vos anciennes traductions Tranzly importées.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Fournisseurs d\'IA','The makers of ChatGPT. A good all-rounder.'=>'Les créateurs de ChatGPT. Un bon outil polyvalent.','The makers of Claude. Strong at writing and careful reasoning.'=>'Les créateurs de Claude. Efficaces en rédaction et dotés d\'un raisonnement minutieux.','Google\'s Gemini models. Fast and inexpensive.'=>'Les modèles Gemini de Google. Rapides et économiques.','A European AI company with fast, inexpensive models.'=>'Une entreprise européenne d\'IA proposant des modèles rapides et économiques.','Low-cost models that are good at writing and code.'=>'Des modèles économiques et performants en rédaction et en code.','One key for models from many different providers.'=>'Une seule clé pour des modèles provenant de nombreux fournisseurs différents.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Tout service fonctionnant comme l\'API de OpenAI, y compris un modèle exécuté sur votre propre ordinateur ou serveur.','General (used when nothing more specific is set)'=>'Général (utilisé lorsqu\'aucun paramètre plus spécifique n\'est défini)','Writing and rewriting'=>'Écriture et réécriture','Translation'=>'Traduction','Code and CSS'=>'Code et CSS','Sorry, you are not allowed to access this page.'=>'Désolé, vous n\'êtes pas autorisé à accéder à cette page.','These settings are shared by every plugin that uses them: %s.'=>'Ces paramètres sont partagés par tous les plugins qui les utilisent : %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vos clés sont chiffrées dans la base de données de ce site et ne sont jamais envoyées qu\'au fournisseur que vous avez choisi — jamais à nous.','Step 1 of 2: choose an AI provider'=>'Étape 1 sur 2 : choisissez un fournisseur d\'IA','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Vous utilisez votre propre clé, vous payez donc directement le fournisseur pour votre consommation. Vous avez un doute ? N\'importe laquelle de ces options conviendra ; vous pourrez en ajouter d\'autres plus tard.','Next'=>'Suivant','Step 2 of 2: connect %s'=>'Étape 2 sur 2 : connecter %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Entrez l\'adresse de votre service compatible avec OpenAI, se terminant par /v1. Une clé n\'est nécessaire que si le service en demande une.','Open %s and sign in (or create a free account).'=>'Ouvrez %s et connectez-vous (ou créez un compte gratuit).','the %s API keys page'=>'la page des clés API %s','Create a new key and copy it.'=>'Créez une nouvelle clé et copiez-la.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Collez-le ci-dessous et appuyez sur « Enregistrer et tester ». Nous envoyons une seule et unique requête pour vérifier que tout fonctionne.','Most providers need a little credit on the account before a key works: %s.'=>'La plupart des fournisseurs nécessitent un petit crédit sur le compte pour qu\'une clé fonctionne : %s.','add credit'=>'ajouter du crédit','← Choose a different provider'=>'← Choisir un autre fournisseur','Address'=>'Adresse','Saved key ends in …%s — paste a new one to replace it'=>'La clé enregistrée se termine par …%s — collez-en une nouvelle pour la remplacer','Key (optional)'=>'Clé (facultative)','API key'=>'Clé API','Save and test'=>'Enregistrer et tester','Providers'=>'Fournisseurs','Provider'=>'Fournisseur','Status'=>'État','Key'=>'Clé','Get a key'=>'Obtenir une clé','Test'=>'Test','Remove'=>'Supprimer','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Enregistré par une version de plugin plus récente : mettez ce plugin à jour ou saisissez à nouveau la clé.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'La clé enregistrée ne peut plus être ouverte (les clés de sécurité du site ont changé). Veuillez la saisir à nouveau.','Not connected'=>'Non connecté','Connected — last test passed %s'=>'Connecté — dernier test réussi %s','Last test failed: %s'=>'Dernier test échoué : %s','Connected — not tested yet'=>'Connecté — pas encore testé','Which model to use'=>'Quel modèle utiliser','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ indique notre recommandation pour cette tâche. La liste inclut tous les modèles que votre clé peut utiliser, actualisés en direct auprès du fournisseur.','— Recommended for the provider —'=>'— Recommandé par le fournisseur —','Save models'=>'Enregistrer les modèles','Refresh the model lists from the providers'=>'Actualiser les listes de modèles des fournisseurs','best quality'=>'meilleure qualité','lowest cost'=>'coût le plus bas','fastest'=>'le plus rapide','Add a model yourself'=>'Ajouter un modèle vous-même','A model came out today? Paste its exact name to use it straight away.'=>'Un nouveau modèle est sorti aujourd\'hui ? Collez son nom exact pour l\'utiliser immédiatement.','Model name'=>'Nom du modèle','Add model'=>'Ajouter un modèle','Recommended models list'=>'Liste des modèles recommandés','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Impossible de vérifier la liste des modèles recommandés, aucune recommandation n\'est donc affichée. Réinstallez l\'extension ou activez les mises à jour quotidiennes ci-dessous.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'La liste utilisée a été publiée le %s. Chaque mise à jour de plugin en apporte une nouvelle.','Also check Zinn Digital® once a day for an updated list.'=>'Consultez également Zinn Digital® une fois par jour pour obtenir une liste mise à jour.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Seule une requête de téléchargement simple est envoyée : aucune clé, aucune adresse de site, rien concernant votre contenu. La liste est signée, et toute liste dont la vérification de la signature échoue est ignorée.','Last checked %1$s: %2$s.'=>'Dernière vérification %1$s : %2$s.','Save, and check now if turned on'=>'Enregistrer, et vérifier maintenant si activé','a newer list was installed'=>'une liste plus récente a été installée','already up to date'=>'déjà à jour','the download failed the signature check and was ignored'=>'le téléchargement a échoué lors de la vérification de la signature et a été ignoré','Zinn Digital® could not be reached; the current list stays in use'=>'Impossible de joindre Zinn Digital® ; la liste actuelle reste en vigueur','turned off'=>'désactivé','Open'=>'Ouvrir','Check their status page'=>'Consulter leur page d\'état','Open your billing page'=>'Ouvrir votre page de facturation','Open your API keys page'=>'Ouvrez votre page de clés API','Open the AI settings'=>'Ouvrir les paramètres de l\'IA','Sorry, you are not allowed to do that.'=>'Désolé, vous n\'avez pas l\'autorisation d\'effectuer cette action.','Unknown provider.'=>'Fournisseur inconnu.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Entrez l\'adresse de votre service, par exemple http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Cela ne ressemble pas à une clé API. Copiez-la à nouveau, sans espaces.','Paste your API key first.'=>'Veuillez d\'abord coller votre clé API.','Key removed.'=>'Clé supprimée.','Models saved.'=>'Modèles enregistrés.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Entrez le nom exact du modèle, tel qu\'il est écrit dans la documentation du fournisseur, par exemple.','Added %s. Choose it under "Which model to use".'=>'Ajouté %s. Choisissez-le sous « Quel modèle utiliser ».','Model removed.'=>'Modèle supprimé.','Daily updates are off. The list that came with the plugin is used.'=>'Les mises à jour quotidiennes sont désactivées. La liste fournie avec le plugin est utilisée.','Checked: %s.'=>'Coché : %s.','Model lists refreshed.'=>'Listes de modèles actualisées.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Votre clé d\'IA a été enregistrée par une version plus récente de l\'un de vos plugins. Mettez ce plugin à jour ou saisissez à nouveau la clé dans les paramètres de l\'IA.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Votre clé IA enregistrée ne peut plus être ouverte (les clés de sécurité du site ont changé). Saisissez-la à nouveau dans les paramètres de l\'IA.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'L\'IA n\'est pas encore configurée. Ajoutez une clé pour un fournisseur d\'IA dans les paramètres de l\'IA.','No model is chosen for this task. Pick one in the AI settings.'=>'Aucun modèle n\'est sélectionné pour cette tâche. Choisissez-en un dans les paramètres de l\'IA.','That AI provider is not supported by this version of the plugin.'=>'Ce fournisseur d\'IA n\'est pas pris en charge par cette version du module.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ce site n\'a pas pu joindre votre service d\'IA. Vérifiez qu\'il est en cours d\'exécution et que son adresse est accessible depuis votre serveur web (un service situé sur votre propre ordinateur n\'est pas accessible depuis un site hébergé).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ce site n\'a pas pu joindre %s. Consultez leur page de status ; s\'ils sont en ligne, votre hébergeur bloque peut-être les connexions sortantes ou l\'adresse est incorrecte.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s indique que votre compte ne dispose plus de crédit ni de quota. Ajoutez du crédit ou augmentez votre limite sur leur compte, puis réessayez.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s n\'a pas accepté votre clé. Elle est peut-être mal saisie, révoquée ou expirée. Créez une nouvelle clé et collez-la ici.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s a refusé cette requête pour votre clé. Il est possible que la clé n\'ait pas accès à ce modèle ou à cette fonctionnalité, ou que votre compte doive être vérifié.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Le modèle "%1$s" n\'est pas disponible auprès de %2$s pour votre clé. Choisissez un autre modèle dans les paramètres de l\'IA.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Votre forfait %2$s n\'inclut pas le modèle "%1$s". Choisissez un autre modèle dans les paramètres d\'IA ou mettez à niveau votre forfait auprès d\'eux.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s limite la vitesse à laquelle votre clé peut envoyer des requêtes. Veuillez patienter une minute et réessayer, ou augmenter votre limite de requêtes auprès de ce service.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s rencontre des problèmes actuellement (une panne ou une surcharge de leur côté). Vos paramètres ne présentent aucun problème. Réessayez sous peu.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'La requête IA a échoué pour une raison que nous n\'avons pas pu identifier. Réessayez ; si le problème persiste, contactez le support en fournissant les détails ci-dessous.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Le fournisseur d\'IA a répondu sous une forme que ce plugin ne peut pas lire. Réessayez ; si le problème persiste, choisissez un autre modèle ou contactez le support.','Custom (OpenAI-compatible)'=>'Personnalisé (compatible OpenAI)','Save a key for this provider first.'=>'Enregistrez d\'abord une clé pour ce fournisseur.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Votre clé fonctionne, mais le fournisseur ne liste aucun modèle de texte pour celle-ci. Ajoutez un modèle vous-même ci-dessous.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Connecté. %1$s a répondu en utilisant %2$s. Vos fonctionnalités d\'IA sont prêtes à être utilisées.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Votre rôle d\'utilisateur ne vous permet pas d\'utiliser l\'IA sur ce site. Contactez un administrateur.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ce site a atteint sa limite de dépenses mensuelles en IA. Un administrateur peut l\'augmenter dans les paramètres de l\'IA.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ce site a atteint sa limite mensuelle de requêtes IA. Un administrateur peut l\'augmenter dans les paramètres de l\'IA.','Usage and cost'=>'Utilisation et coût','The log, limits and role permissions apply to AI used through: %s.'=>'Le journal, les limites et les autorisations des rôles s\'appliquent à l\'IA utilisée via : %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Les coûts sont approximatifs, calculés à partir des prix publiés ; un modèle sans prix connu est compté comme zéro.','This month: %1$s requests, about %2$s.'=>'Ce mois-ci : %1$s requêtes, soit environ %2$s.','When'=>'Quand','Who'=>'Qui','Used for'=>'Utilisé pour','Model'=>'Modèle','Tokens in / out'=>'Jetons d\'entrée / de sortie','About'=>'À propos','Result'=>'Résultat','No AI requests have been made yet.'=>'Aucune requête d\'IA n\'a encore été effectuée.','Done'=>'Terminé','Limits and permissions'=>'Limites et autorisations','Monthly spending limit (US dollars)'=>'Limite de dépenses mensuelle (dollars US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Laisser vide pour désactiver la limite. L\'IA s\'arrête pour le reste du mois dès que le coût estimé l\'atteint.','Monthly request limit'=>'Limite de requêtes mensuelles','Leave empty for no limit.'=>'Laissez vide pour ne définir aucune limite.','Who may use AI'=>'Qui peut utiliser l\'IA','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Ne cochez rien pour permettre à toute personne pouvant utiliser les fonctionnalités du plugin d\'utiliser l\'IA. Les administrateurs peuvent toujours l\'utiliser.','Save limits and permissions'=>'Enregistrer les limites et les autorisations','Limits and permissions saved.'=>'Limites et autorisations enregistrées.','That language is not one of this site\'s languages.'=>'Cette langue ne fait pas partie des langues de ce site.','A translation must be the same kind of content as the original.'=>'Une traduction doit être du même type de contenu que l\'original.','Choose one of the site\'s other languages.'=>'Choisissez une autre langue du site.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Les scripts de l\'écran d\'administration manquent dans cette copie du plugin. Réinstallez-le à partir d\'un paquet publié.','This screen needs JavaScript.'=>'Cet écran nécessite JavaScript.','Choose a language'=>'Choisir une langue','Upgrade'=>'Mettre à niveau','Pricing'=>'Tarifs','Start Trial'=>'Démarrer l\'essai','Account'=>'Compte','Contact Us'=>'Contactez-nous','Affiliation'=>'Affiliation','the kind of softwarePlugin'=>'Extension','greetingHey %s,'=>'Bonjour %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Abonnez-vous pour recevoir des notifications par e-mail concernant les mises à jour de sécurité et de fonctionnalités, du contenu pédagogique et des offres occasionnelles, et pour partager quelques informations de base sur l\'environnement WordPress. Cela nous aidera à rendre %s plus compatible avec votre site et plus performant pour répondre à vos besoins.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Inscrivez-vous pour recevoir des notifications par e-mail concernant les mises à jour de sécurité et de fonctionnalités, du contenu éducatif et des offres occasionnelles, et pour partager quelques informations de base sur l\'environnement WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Si vous passez cette étape, ce n\'est pas grave ! %1$s continuera de fonctionner parfaitement.','Allow & Continue'=>'Autoriser et continuer','verbSkip'=>'Ignorer','Skipping, please wait'=>'Ignorant, veuillez patienter','Continue'=>'Continuer','Please wait'=>'Veuillez patienter','as activating pluginActivating'=>'En cours d\'activation','This will allow %s to'=>'Cela permettra à %s de','Privacy Policy'=>'Politique de confidentialité','Terms of Service'=>'Conditions d\'utilisation','License Agreement'=>'Contrat de licence','Have a license key?'=>'Possédez-vous une clé de licence ?','Activate License'=>'Activer la licence','View Basic Profile Info'=>'Afficher les informations du profil de base','Your WordPress user\'s: first & last name, and email address'=>'Vos nom, prénom et adresse e-mail d\'utilisateur WordPress','View Basic Website Info'=>'Afficher les informations de base du site web','Homepage URL & title, WP & PHP versions, and site language'=>'URL et titre de la page d\'accueil, versions WP et PHP, et langue du site','View Basic %s Info'=>'Afficher les informations de base de %s','Current %s & SDK versions, and if active or uninstalled'=>'Versions actuelles %s et SDK, et état d\'activité ou de désinstallation','Newsletter'=>'Bulletin d\'information','Updates, announcements, marketing, no spam'=>'Mises à jour, annonces, marketing, pas de spam','View Diagnostic Info'=>'Afficher les informations de diagnostic','WordPress & PHP versions, site language & title'=>'Versions de WordPress et PHP, langue et titre du site','View Plugins & Themes List'=>'Afficher la liste des extensions et thèmes','Names, slugs, versions, and if active or not'=>'Noms, slugs, versions, et état d\'activité','optional'=>'optionnel','Never miss an important update'=>'Ne manquez jamais une mise à jour importante','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Nous avons introduit cette option afin que vous ne manquiez jamais une mise à jour importante et pour nous aider à rendre %s plus compatible avec votre site et plus efficace pour répondre à vos besoins.','Thank you for updating to %1$s v%2$s!'=>'Merci d\'avoir mis à jour vers %1$s v%2$s !','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Le préfixe doit comporter de 1 à 8 lettres minuscules ou chiffres, commencer par une lettre et ne pas correspondre au nom du module d\'extension.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" n\'est pas un code de langue. Utilisez une locale WordPress telle que fr_FR ou de_DE.','List at least one language.'=>'Veuillez lister au moins une langue.','You are not allowed to translate this item.'=>'Vous n\'êtes pas autorisé à traduire cet élément.','This item already has a version in that language.'=>'Cet élément possède déjà une version dans cette langue.','That translation engine is not available on this site.'=>'Ce moteur de traduction n\'est pas disponible sur ce site.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Les moteurs différents par langue, la solution de repli automatique et les plafonds de dépenses sont des fonctionnalités de Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Chaque langue doit être l\'une des langues du site, avec un moteur disponible.','The fallback list may only name available engines.'=>'La liste de secours ne peut désigner que des moteurs disponibles.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Une limite mensuelle est un montant en dollars US, égal ou supérieur à zéro, pour un moteur disponible.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Les traductions privilégiées et le ton par langue sont des fonctionnalités de Tranzly Pro. La liste des termes à ne pas traduire est gratuite.','Glossary entries must be grouped by one of the site\'s languages.'=>'Les entrées du glossaire doivent être regroupées par l\'une des langues du site.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Le ton est défini par langue de site : niveau de formalité par défaut, plus ou moins, ainsi que des instructions facultatives.','The value for %s is not one of the allowed choices.'=>'La valeur pour %s ne fait pas partie des choix autorisés.','The background queue is not available on this site.'=>'La file d\'attente d\'arrière-plan n\'est pas disponible sur ce site.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Un travail de traduction s\'exécute en tant que la personne qui le lance, un utilisateur doit donc être connecté.','There is nothing you are allowed to translate in that selection.'=>'Il n\'y a rien que vous soyez autorisé à traduire dans cette sélection.','That item is not part of a translation job.'=>'Cet article ne fait pas partie d\'une tâche de traduction.','You are not allowed to change that translation.'=>'Vous n\'avez pas le droit de modifier cette traduction.','This item\'s group already has a %1$s version (#%2$d).'=>'Le groupe de cet élément possède déjà une version %1$s (#%2$d).','An item cannot be its own translation.'=>'Un élément ne peut pas être sa propre traduction.','That item is already a translation of something else. Unlink it first.'=>'Cet élément est déjà la traduction d\'autre chose. Dissociez-le d\'abord.','The translation link could not be saved.'=>'Le lien de traduction n\'a pas pu être enregistré.','That text cannot be translated here.'=>'Ce texte ne peut pas être traduit ici.','That media text cannot be translated here.'=>'Ce texte multimédia ne peut pas être traduit ici.','A translation can be published or kept as a draft.'=>'Une traduction peut être publiée ou enregistrée comme brouillon.','You are not allowed to publish this kind of content.'=>'Vous n\'êtes pas autorisé à publier ce type de contenu.','This item is already written in that language.'=>'Cet élément est déjà rédigé dans cette langue.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Cette traduction a été modifiée par une personne (ou importée) et est donc protégée. Déverrouillez-la pour la retraduire.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Aucun moteur de traduction n\'est encore configuré. Ajoutez une clé pour l\'un d\'eux dans Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Ce moteur de traduction n\'est pas encore configuré : ajoutez d\'abord sa clé.','The same text is being translated by another job right now; this item will use that answer.'=>'Le même texte est déjà en cours de traduction par une autre tâche ; cet élément utilisera cette réponse.','No translation engine could take this item.'=>'Aucun moteur de traduction n\'a pu prendre cet élément.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Le moteur n\'a pas renvoyé de traduction pour toutes les parties de cet élément. Aucune modification n\'a été apportée.','AI model'=>'Modèle d\'IA','AI model (%1$s %2$s)'=>'Modèle d\'IA (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s rencontre des problèmes actuellement. Veuillez réessayer sous peu ou utiliser un autre moteur.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Votre site n\'a pas pu joindre %s. Vérifiez qu\'il peut établir des connexions sortantes, puis réessayez.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s n\'a pas accepté votre clé API. Vérifiez la clé dans Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Votre compte %s a épuisé son quota ou son solde. Rechargez-le auprès d\'eux, ou utilisez un autre moteur.','%s asked us to slow down. It will be tried again automatically.'=>'%s nous a demandé de ralentir. Une nouvelle tentative sera effectuée automatiquement.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Ce texte est trop long pour %s en une seule fois. Divisez le contenu ou utilisez un autre moteur.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s a refusé de traduire ce contenu. Essayez un autre moteur ou traduisez-le manuellement.','%s does not translate this language. Choose another engine for it.'=>'%s ne prend pas en charge cette langue. Choisissez un autre moteur pour celle-ci.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Le plafond de dépenses de ce mois-ci pour %s est atteint, aucun envoi supplémentaire n\'a donc été effectué. Augmentez le plafond dans Tranzly → Engines, ou patientez jusqu\'à mois prochain.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'La traduction avec %s a échoué pour une raison que Tranzly n\'a pas pu identifier. Les détails figurent ci-dessous.','An engine id must be lowercase letters, digits and hyphens.'=>'Un identifiant de moteur doit être composé exclusivement de lettres minuscules, de chiffres et de tirets.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Développé par Neil Lock, PDG de Zinn Digital® Ltd','Version %s'=>'Version %s','Tranzly website'=>'Site Web Tranzly','Zinn Digital® website'=>'site Web Zinn Digital®','Settings saved.'=>'Paramètres enregistrés.','See the Pro plans and pricing'=>'Voir les forfaits Pro et les tarifs','Languages'=>'Langues','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'La première langue est celle dans laquelle votre contenu est rédigé. Les visiteurs basculent grâce au bloc de sélection de langue.','(default)'=>'(par défaut)','Locale code'=>'Code de langue','For example fr_FR'=>'Par exemple fr_FR','Name (optional)'=>'Nom (facultatif)','For example Français'=>'Par exemple Français','Add language'=>'Ajouter une langue','Front-end output'=>'Sortie front-end','Class name prefix'=>'Préfixe de nom de classe','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Chaque nom de classe que le plugin affiche sur vos pages commence par ce préfixe, afin que les pages ne révèlent pas quel plugin les a créées. 1 à 8 lettres minuscules ou chiffres, commençant par une lettre.','Beta updates'=>'Mises à jour bêta','This site receives beta versions as updates.'=>'Ce site reçoit des versions bêta en guise de mises à jour.','This site receives stable versions only.'=>'Ce site reçoit uniquement des versions stables.','Change this on the Account page'=>'Modifiez ceci sur la page Compte','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Les versions bêta sont proposées aux installations Pro sous licence qui sont connectées à leur compte. Une fois connecté, vous pouvez participer depuis la page Compte.','Save settings'=>'Enregistrer les paramètres','First engine that is set up'=>'Premier moteur configuré','Key saved. It is stored encrypted and never shown again.'=>'Clé enregistrée. Elle est stockée de manière chiffrée et ne sera plus jamais affichée.','Engine settings saved.'=>'Paramètres du moteur enregistrés.','Glossary saved.'=>'Glossaire enregistré.','Your keys'=>'Vos clés','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly appelle les services de traduction avec votre propre compte. Les clés sont stockées de manière chiffrée dans votre base de données et ne sont jamais envoyées qu\'au service auquel elles appartiennent. Les clés des modèles d\'IA sont configurées dans les paramètres de l\'IA.','%s API key'=>'Clé API %s','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Enregistré : %s. Entrez une nouvelle clé pour la remplacer, ou enregistrez un champ vide pour la supprimer.','No key saved.'=>'Aucune clé enregistrée.','Azure region (leave empty for a global resource)'=>'Région Azure (laisser vide pour une ressource globale)','Save key'=>'Enregistrer la clé','Check my DeepL usage'=>'Consulter mon utilisation de DeepL','%1$s of %2$s characters used this billing period.'=>'%1$s sur %2$s caractères utilisés pour cette période de facturation.','Which engine translates'=>'Quel moteur traduit','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Aucun moteur n\'est encore configuré. Enregistrez une clé ci-dessus (ou configurez un modèle d\'IA) pour commencer la traduction.','Default engine'=>'Moteur par défaut','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Un moteur différent par langue, le repli automatique et les plafonds de dépenses mensuels sont des fonctionnalités de Tranzly Pro.','Engine for %s'=>'Moteur pour %s','The default engine'=>'Le moteur par défaut','If an engine fails or reaches a limit, try these next, in this order'=>'Si un moteur tombe en panne ou atteint une limite, essayez les solutions suivantes, dans cet ordre','Monthly spending caps'=>'Plafonds de dépenses mensuels','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Lorsqu\'un moteur atteint sa limite, rien de plus ne lui est envoyé jusqu\'au mois prochain et le rapport de traduction échoué en indique la raison. Laissez vide pour ne définir aucune limite.','%1$s (spent this month: $%2$s)'=>'%1$s (dépensé ce mois-ci : $%2$s)','Save caps'=>'Enregistrer les majuscules','Glossary and words never translated'=>'Glossaire et mots jamais traduits','Never translate these words (one per line)'=>'Ne jamais traduire ces mots','Brand and product names stay exactly as they are, with every engine.'=>'Les noms de marque et de produits restent exactement tels quels, quel que soit le moteur.','Preferred translations and tone per language are Tranzly Pro features.'=>'Les traductions préférées et le ton par langue sont des fonctionnalités de Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Traductions préférées (une par ligne : terme = traduction)','Formality'=>'Formalité','Default'=>'Par défaut','Formal'=>'Formel','Informal'=>'Officieux','Style instructions (audience, brand voice)'=>'Consignes de style (public cible, voix de la marque)','Save glossary'=>'Enregistrer le glossaire','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Travail démarré avec %d traductions à effectuer. Il s\'exécute en arrière-plan : vous pouvez fermer cette page.','Queued again.'=>'Mis en file d\'attente à nouveau.','Running'=>'En cours d\'exécution','Finished'=>'Terminé','Cancelled'=>'Annulé','Translate in the background'=>'Traduire en arrière-plan','Set up a translation engine in the Engines tab first.'=>'Configurez d\'abord un moteur de traduction dans l\'onglet Moteurs.','Translate every'=>'Traduire tout','Into'=>'Dans','With'=>'Avec','Each language’s own engine'=>'Le propre moteur de chaque langue','Publish the translations (otherwise they are saved as drafts)'=>'Publiez les traductions (elles sont sinon enregistrées comme brouillons)','Estimate the cost'=>'Estimer le coût','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d publications, %2$s caractères. Le prix de ce moteur n\'est pas connu à l\'avance.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d articles, %2$s caractères : environ $%3$s sur votre propre compte.','Start translating'=>'Commencer la traduction','Jobs'=>'Tâches','No translation jobs yet.'=>'Aucune tâche de traduction pour le moment.','Job %1$d — %2$s'=>'Tâche %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d sur %2$d traduits, %3$d échecs, %4$d ignorés (protégés ou déjà dans cette langue)','Stop this job'=>'Arrêter cette tâche','See what failed and why'=>'Découvrez ce qui a échoué et pourquoi','Content'=>'Contenu','Language'=>'Langue','What went wrong'=>'Où est l\'erreur','Fix it'=>'Corriger','Details'=>'Détails','Retry with'=>'Réessayer avec','The same engine'=>'Le même moteur','Retry'=>'Réessayer','Translate by hand'=>'Traduire manuellement','Languages and settings'=>'Langues et paramètres','Engines'=>'Moteurs','Translation jobs'=>'Travaux de traduction','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Ajoutez une deuxième langue sous Tranzly dans le menu d\'administration, et le sélecteur apparaîtra ici.','Switcher'=>'Sélecteur','Accessible label'=>'Étiquette accessible','block titleLanguage switcher'=>'Sélecteur de langue','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Liens vers cette page dans chacune des langues du site. Aucun contenu n\'est affiché tant qu\'il n\'y a pas au moins deux langues répertoriées.','block keywordlanguage'=>'langue','block keywordswitcher'=>'sélecteur','block keywordtranslation'=>'traduction']];